/**
 * Unit tests for PolygonsSet.computeGeometricalProperties.
 * Since the method is protected, we use a Testable subclass to access it.
 */
public class PolygonsSet_computeGeometricalProperties_TriageGen0Test {

    /**
     * Subclass to expose the protected method for testing.
     */
    private static class TestablePolygonsSet extends PolygonsSet {
        private Vector2D[][] vertices;
        private BSPTree<Euclidean2D> mockTree;

        public TestablePolygonsSet(Vector2D[][] vertices, BSPTree<Euclidean2D> tree) {
            super();
            this.vertices = vertices;
            this.mockTree = tree;
        }

        @Override
        public Vector2D[][] getVertices() {
            return vertices;
        }

        @Override
        protected BSPTree<Euclidean2D> getTree(boolean b) {
            return mockTree;
        }

        @Override
        public void computeGeometricalProperties() {
            super.computeGeometricalProperties();
        }
    }

    @Test
    public void testEmptyVertices_TreeAttributeTrue() {
        BSPTree<Euclidean2D> tree = mock(BSPTree.class);
        when(tree.getAttribute()).thenReturn(true);

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(new Vector2D[0][0], tree);
        polygonsSet.computeGeometricalProperties();

        assertEquals(Double.POSITIVE_INFINITY, polygonsSet.getSize(), 1e-10);
        assertEquals(Vector2D.NaN, polygonsSet.getBarycenter());
    }

    @Test
    public void testEmptyVertices_TreeAttributeFalse() {
        BSPTree<Euclidean2D> tree = mock(BSPTree.class);
        when(tree.getAttribute()).thenReturn(false);

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(new Vector2D[0][0], tree);
        polygonsSet.computeGeometricalProperties();

        assertEquals(0.0, polygonsSet.getSize(), 1e-10);
        assertEquals(new Vector2D(0, 0), polygonsSet.getBarycenter());
    }

    @Test
    public void testOpenLoop_NullVertex() {
        // v[0][0] == null signifies an open loop
        Vector2D[][] vertices = new Vector2D[1][1];
        vertices[0][0] = null;

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(vertices, null);
        polygonsSet.computeGeometricalProperties();

        assertEquals(Double.POSITIVE_INFINITY, polygonsSet.getSize(), 1e-10);
        assertEquals(Vector2D.NaN, polygonsSet.getBarycenter());
    }

    @Test
    public void testClosedLoop_PositiveArea() {
        // A simple 1x1 square: (0,0), (1,0), (1,1), (0,1)
        Vector2D[][] vertices = {
            { new Vector2D(0, 0), new Vector2D(1, 0), new Vector2D(1, 1), new Vector2D(0, 1) }
        };

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(vertices, null);
        polygonsSet.computeGeometricalProperties();

        // Area should be 1.0
        assertEquals(1.0, polygonsSet.getSize(), 1e-10);
        // Barycenter should be (0.5, 0.5)
        assertEquals(new Vector2D(0.5, 0.5), polygonsSet.getBarycenter());
    }

    @Test
    public void testClosedLoop_NegativeArea_InfiniteInside() {
        // A square with clockwise winding (negative area in this formula)
        // (0,0), (0,1), (1,1), (1,0)
        Vector2D[][] vertices = {
            { new Vector2D(0, 0), new Vector2D(0, 1), new Vector2D(1, 1), new Vector2D(1, 0) }
        };

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(vertices, null);
        polygonsSet.computeGeometricalProperties();

        // If sum < 0, it sets size to Infinity and barycenter to NaN
        assertEquals(Double.POSITIVE_INFINITY, polygonsSet.getSize(), 1e-10);
        assertEquals(Vector2D.NaN, polygonsSet.getBarycenter());
    }

    @Test
    public void testClosedLoop_MultipleLoops() {
        // Two separate squares: 
        // Square 1: (0,0), (1,0), (1,1), (0,1) -> Area 1, Barycenter (0.5, 0.5)
        // Square 2: (2,0), (3,0), (3,1), (2,1) -> Area 1, Barycenter (2.5, 0.5)
        // Total Area: 2.0
        // Combined Barycenter: ( (1*0.5 + 1*2.5)/2, (1*0.5 + 1*0.5)/2 ) = (1.5, 0.5)
        Vector2D[][] vertices = {
            { new Vector2D(0, 0), new Vector2D(1, 0), new Vector2D(1, 1), new Vector2D(0, 1) },
            { new Vector2D(2, 0), new Vector2D(3, 0), new Vector2D(3, 1), new Vector2D(2, 1) }
        };

        TestablePolygonsSet polygonsSet = new TestablePolygonsSet(vertices, null);
        polygonsSet.computeGeometricalProperties();

        assertEquals(2.0, polygonsSet.getSize(), 1e-10);
        assertEquals(new Vector2D(1.5, 0.5), polygonsSet.getBarycenter());
    }
}
